SourceCode.Declaration:
/// <summary>
/// An expression used to retrieve the company image, that is used for reports.
/// </summary>
[TFMDescription("An expression used to retrieve the company image, that is used for reports, as a base64 image.")]
class TFMExpressionsCompanyImage extends TFMExpressions
{
}

Method.Source:
public str processExpressionCommon(Common _common)
{
    Bitmap bmp = FormLetter::companyLogo();//CompanyImage::findByRecord(CompanyInfo::find()).Image;
    BinData     bin = new BinData();
    str         ret;
    if (bmp == conNull())
    {
        return '';
    }
    bin.setData(bmp);
    ret = bin.base64Encode();
    return ret;
}
